INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\ndef calculate_average(numbers):\n    sum = 0\n    for num in numbers:\n        sum += num\n    average = sum / len(numbers)\n    return average\n```\nWelcher Fehler tritt bei leerer Liste auf?', 3, '[{"text": "Division durch Null", "correct": true, "because": "len(numbers) ist 0"}, {"text": "Typfehler", "correct": false, "because": "Keine Typprüfung"}, {"text": "Syntaxfehler", "correct": false, "because": "Syntax korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\ndef main():\n    input_list = [1, 2, "3", 4, -1, 0]\n    positive_numbers = process_data(input_list)\n```\nWelcher Fehler tritt in input_list auf?', 2, '[{"text": "Typfehler: String statt Integer", "correct": true, "because": "\"3\" ist String"}, {"text": "Indexfehler", "correct": false, "because": "Index korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\ndef process_data(data):\n    result = []\n    for i in range(len(data)):\n        if data[i] > 0:\n            result.append(data[i] * 2)\n        else:\n            result.append(data[i])\n    return result\n```\nWelcher Fehler tritt bei "3" auf?', 3, '[{"text": "TypeError bei Vergleich", "correct": true, "because": "String > 0 nicht möglich"}, {"text": "Syntaxfehler", "correct": false, "because": "Syntax korrekt"}, {"text": "Kein Fehler", "correct": false, "because": "Typproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\n    for num in positive_numbers:\n        if num > 5:\n            print(num + " ist größer als 5")\n```\nWelcher Fehler tritt in der Ausgabe auf?', 3, '[{"text": "TypeError: Integer + String", "correct": true, "because": "num + String nicht möglich"}, {"text": "Indexfehler", "correct": false, "because": "Schleife korrekt"}, {"text": "Syntaxfehler", "correct": false, "because": "Syntax korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie kann der Fehler in calculate_average bei leerer Liste behoben werden?', 2, '[{"text": "If-Abfrage für len(numbers) > 0", "correct": true, "because": "Verhindert Division durch 0"}, {"text": "Summe auf 1 setzen", "correct": false, "because": "Falsches Ergebnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\ninput_list = [1, 2, "3", 4, -1, 0]\n```\nWie kann der Typfehler in input_list behoben werden?', 3, '[{"text": "String in Integer umwandeln", "correct": true, "because": "int(\"3\") löst Problem"}, {"text": "String ignorieren", "correct": false, "because": "Fehler bleibt"}, {"text": "Liste löschen", "correct": false, "because": "Nicht zielführend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler tritt bei ```python\nprint(num + " ist größer als 5")\n``` auf?', 2, '[{"text": "TypeError", "correct": true, "because": "Integer + String"}, {"text": "Syntaxfehler", "correct": false, "because": "Syntax korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie kann der Fehler in der Ausgabe behoben werden?', 3, '[{"text": "str(num) + \" ist größer als 5\"", "correct": true, "because": "Konvertiert Integer zu String"}, {"text": "Schleife entfernen", "correct": false, "because": "Nicht zielführend"}, {"text": "print(num)", "correct": false, "because": "Text fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\nsum += num\n```\nWelcher Fehler tritt bei "3" auf?', 3, '[{"text": "TypeError: String + Integer", "correct": true, "because": "String nicht addierbar"}, {"text": "Indexfehler", "correct": false, "because": "Index korrekt"}, {"text": "Kein Fehler", "correct": false, "because": "Typproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode findet den Typfehler in input_list?', 2, '[{"text": "Debugging mit type()", "correct": true, "because": "Zeigt String"}, {"text": "Code überspringen", "correct": false, "because": "Fehler bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Gegeben: ```python\naverage = sum / len(numbers)\n```\nWas passiert bei leerer Liste?', 3, '[{"text": "ZeroDivisionError", "correct": true, "because": "Division durch 0"}, {"text": "Kein Fehler", "correct": false, "because": "Exception entsteht"}, {"text": "Typfehler", "correct": false, "because": "Kein Typproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler tritt bei ```python\nresult.append(data[i] * 2)\n``` mit "3" auf?', 3, '[{"text": "TypeError bei String", "correct": true, "because": "String * 2 nicht numerisch"}, {"text": "Indexfehler", "correct": false, "because": "Index korrekt"}, {"text": "Syntaxfehler", "correct": false, "because": "Syntax korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie kann process_data den Typfehler vermeiden?', 2, '[{"text": "Typprüfung mit isinstance()", "correct": true, "because": "Prüft Typen"}, {"text": "Liste ignorieren", "correct": false, "because": "Fehler bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeile in main() verursacht den Typfehler bei der Ausgabe?', 3, '[{"text": "print(num + \" ist größer als 5\")", "correct": true, "because": "String + Integer"}, {"text": "avg = calculate_average()", "correct": false, "because": "Kein Typfehler"}, {"text": "for num in positive_numbers", "correct": false, "because": "Schleife korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode findet den Fehler in calculate_average?', 2, '[{"text": "Unit-Test mit leerer Liste", "correct": true, "because": "Prüft Division"}, {"text": "Code löschen", "correct": false, "because": "Nicht zielführend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler tritt bei ```python\nif data[i] > 0:\n``` mit "3" auf?', 3, '[{"text": "TypeError", "correct": true, "because": "String > Integer nicht möglich"}, {"text": "Syntaxfehler", "correct": false, "because": "Syntax korrekt"}, {"text": "Kein Fehler", "correct": false, "because": "Typproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie kann der Fehler in process_data behoben werden?', 3, '[{"text": "int(data[i]) konvertieren", "correct": true, "because": "String zu Integer"}, {"text": "if entfernen", "correct": false, "because": "Logik fehlt"}, {"text": "data[i] ignorieren", "correct": false, "because": "Fehler bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeile in calculate_average verursacht den Fehler bei leerer Liste?', 2, '[{"text": "average = sum / len(numbers)", "correct": true, "because": "Division durch 0"}, {"text": "sum += num", "correct": false, "because": "Kein Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode findet den Typfehler in der Ausgabe?', 3, '[{"text": "Debugger mit Breakpoint", "correct": true, "because": "Zeigt Typkonflikt"}, {"text": "Code ignorieren", "correct": false, "because": "Fehler bleibt"}, {"text": "Hardware prüfen", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler könnte durch ```python\ninput_list = [1, 2, "3", 4, -1, 0]\n``` übersehen werden?', 3, '[{"text": "Typfehler bei Berechnungen", "correct": true, "because": "String in Liste"}, {"text": "Indexfehler", "correct": false, "because": "Index korrekt"}, {"text": "Kein Fehler", "correct": false, "because": "Typproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie kann der Fehler in calculate_average dokumentiert werden?', 2, '[{"text": "Kommentar hinzufügen", "correct": true, "because": "Erklärt Problem"}, {"text": "Code löschen", "correct": false, "because": "Nicht zielführend"}]');
